"""Small standard-library client for OpenAI's Responses API.

The module keeps prompts in memory only and sends them directly to OpenAI over
HTTPS. It does not log, cache, or persist prompt text.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Iterable, Mapping, Optional


DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")


class OpenAIClientError(RuntimeError):
    """Raised when the Responses API request cannot be completed."""

    def __init__(
        self,
        message: str,
        *,
        status: Optional[int] = None,
        request_id: Optional[str] = None,
        error: Optional[Mapping[str, Any]] = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.request_id = request_id
        self.error = dict(error or {})


class OpenAIClient:
    """Minimal OpenAI Responses API client using only Python's standard library."""

    def __init__(
        self,
        api_key: Optional[str] = None,
        *,
        model: str = DEFAULT_MODEL,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = 60.0,
        organization: Optional[str] = None,
        project: Optional[str] = None,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIClientError("Missing API key. Set OPENAI_API_KEY or pass api_key.")

        self.model = model
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")
        self.project = project or os.environ.get("OPENAI_PROJECT_ID")

    def create_response(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
        metadata: Optional[Mapping[str, str]] = None,
        extra: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Send a text prompt and return the raw Responses API JSON object."""

        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")

        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            payload["temperature"] = temperature
        if metadata is not None:
            payload["metadata"] = dict(metadata)
        if extra:
            payload.update(dict(extra))

        return self._post_json("/responses", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send a text prompt and return only the assistant's text output."""

        response = self.create_response(prompt, **kwargs)
        return extract_text(response)

    def _post_json(self, path: str, payload: Mapping[str, Any]) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "stdlib-openai-responses-client/1.0",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project

        request = urllib.request.Request(url, data=data, headers=headers, method="POST")

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                body = response.read()
                request_id = response.headers.get("x-request-id")
                return _decode_json_response(body, request_id=request_id)
        except urllib.error.HTTPError as exc:
            body = exc.read()
            request_id = exc.headers.get("x-request-id") if exc.headers else None
            error_payload = _safe_json(body)
            error_detail = error_payload.get("error", error_payload)
            message = _error_message(error_detail, exc.reason)
            raise OpenAIClientError(
                message,
                status=exc.code,
                request_id=request_id,
                error=error_detail if isinstance(error_detail, Mapping) else error_payload,
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIClientError(f"Could not reach OpenAI API: {exc.reason}") from exc


def create_response(prompt: str, **kwargs: Any) -> Dict[str, Any]:
    """Convenience wrapper around ``OpenAIClient().create_response(...)``."""

    client_kwargs = _client_kwargs_from(kwargs)
    return OpenAIClient(**client_kwargs).create_response(prompt, **kwargs)


def ask(prompt: str, **kwargs: Any) -> str:
    """Convenience wrapper around ``OpenAIClient().ask(...)``."""

    client_kwargs = _client_kwargs_from(kwargs)
    return OpenAIClient(**client_kwargs).ask(prompt, **kwargs)


def extract_text(response: Mapping[str, Any]) -> str:
    """Extract assistant text from a Responses API response object."""

    direct_text = response.get("output_text")
    if isinstance(direct_text, str):
        return direct_text

    parts = []
    output = response.get("output", [])
    if isinstance(output, Iterable) and not isinstance(output, (str, bytes, Mapping)):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            content = item.get("content", [])
            if not isinstance(content, Iterable) or isinstance(content, (str, bytes, Mapping)):
                continue
            for block in content:
                if not isinstance(block, Mapping):
                    continue
                if block.get("type") in {"output_text", "text"}:
                    text = block.get("text")
                    if isinstance(text, str):
                        parts.append(text)

    return "".join(parts)


def _client_kwargs_from(kwargs: Dict[str, Any]) -> Dict[str, Any]:
    client_keys = {"api_key", "base_url", "timeout", "organization", "project"}
    client_kwargs = {key: kwargs.pop(key) for key in list(kwargs) if key in client_keys}
    return client_kwargs


def _decode_json_response(body: bytes, *, request_id: Optional[str]) -> Dict[str, Any]:
    try:
        decoded = json.loads(body.decode("utf-8"))
    except json.JSONDecodeError as exc:
        raise OpenAIClientError(
            "OpenAI API returned invalid JSON.",
            request_id=request_id,
        ) from exc

    if not isinstance(decoded, dict):
        raise OpenAIClientError(
            "OpenAI API returned an unexpected JSON value.",
            request_id=request_id,
        )
    return decoded


def _safe_json(body: bytes) -> Dict[str, Any]:
    try:
        decoded = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return {}
    return decoded if isinstance(decoded, dict) else {}


def _error_message(error_detail: Any, fallback: str) -> str:
    if isinstance(error_detail, Mapping):
        message = error_detail.get("message")
        if isinstance(message, str) and message:
            return message
    return f"OpenAI API request failed: {fallback}"


def _main() -> int:
    prompt = sys.stdin.read()
    if not prompt.strip():
        sys.stderr.write("Read a prompt from stdin, for example: echo 'Hello' | python openai_client.py\n")
        return 2

    sys.stdout.write(ask(prompt))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(_main())

