/bin/bash -lc "python3 - <<'PY'
import json
import urllib.request
from openai_client import OpenAIClient, extract_text

captured = {}

class Response:
    headers = {'x-request-id': 'req_test'}
    def __enter__(self):
        return self
    def __exit__(self, *args):
        return False
    def read(self):
        return json.dumps({'output': [{'content': [{'type': 'output_text', 'text': 'ok'}]}]}).encode()

def fake_urlopen(request, timeout):
    captured['url'] = request.full_url
    captured['timeout'] = timeout
    captured['headers'] = dict(request.header_items())
    captured['payload'] = json.loads(request.data.decode())
    return Response()

real_urlopen = urllib.request.urlopen
urllib.request.urlopen = fake_urlopen
try:
    client = OpenAIClient(api_key='[REDACTED_SECRET]', model='test-model', timeout=7)
    response = client.create_response('private prompt')
finally:
    urllib.request.urlopen = real_urlopen

print(captured['url'])
print(captured['payload'])
print(extract_text(response))
PY"

